package dominoes

// Domino represents a domino tile with two halves.
type Domino [2]int

// MakeChain computes a way to order the given dominoes so they form a
// correct closed domino chain, or reports that no such chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
    n := len(input)
    if n == 0 {
        return []Domino{}, true
    }

    chain := make([]Domino, 0, n)
    used := make([]bool, n)

    var backtrack func() bool
    backtrack = func() bool {
        if len(chain) == n {
            // All dominoes placed; check the ends match.
            return chain[0][0] == chain[len(chain)-1][1]
        }

        var next int
        if len(chain) == 0 {
            next = -1
        } else {
            next = chain[len(chain)-1][1]
        }

        for i := 0; i < n; i++ {
            if used[i] {
                continue
            }
            a, b := input[i][0], input[i][1]
            // Try placing domino i so that it connects to `next`.
            if len(chain) == 0 {
                // First domino: try both orientations.
                for _, d := range []Domino{{a, b}, {b, a}} {
                    chain = append(chain, d)
                    used[i] = true
                    if backtrack() {
                        return true
                    }
                    used[i] = false
                    chain = chain[:len(chain)-1]
                }
            } else {
                // Must connect: one end equals next.
                if a == next {
                    chain = append(chain, Domino{a, b})
                    used[i] = true
                    if backtrack() {
                        return true
                    }
                    used[i] = false
                    chain = chain[:len(chain)-1]
                }
                if b == next {
                    chain = append(chain, Domino{b, a})
                    used[i] = true
                    if backtrack() {
                        return true
                    }
                    used[i] = false
                    chain = chain[:len(chain)-1]
                }
            }
        }
        return false
    }

    ok := backtrack()
    if ok {
        return chain, true
    }
    return nil, false
}
```

